output_text:
[
  {
    "id": "no_carts_in_single_file_aisles",
    "text": "Shopping carts are prohibited in single-file shelf aisles.",
    "abstraction": {
      "state_properties": {
        "singleFileAisle": {
          "le": [
            "freeWidthH",
            1
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "hasCart",
          "singleFileAisle"
        ]
      }
    }
  },
  {
    "id": "no_cart_entry_to_single_file_aisle",
    "text": "A shopper must not enter a single-file shelf aisle while still holding a cart.",
    "abstraction": {
      "state_properties": {
        "singleFileAisle": {
          "le": [
            "freeWidthH",
            1
          ]
        }
      },
      "events": {
        "enterSingleFileWithCart": {
          "pre": {
            "and": [
              "hasCart",
              {
                "not": "singleFileAisle"
              },
              "MOVE"
            ]
          },
          "post": "singleFileAisle"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "enterSingleFileWithCart"
    }
  },
  {
    "id": "no_cart_shelf_pickup_between_shelves",
    "text": "Items located in narrow aisles between opposing shelves must be picked up without a cart.",
    "abstraction": {
      "state_properties": {
        "betweenOpposingShelves": {
          "and": [
            "adjShelf",
            "shelfE",
            "shelfW",
            {
              "le": [
                "freeWidthH",
                1
              ]
            }
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "INTERACT",
          "betweenOpposingShelves",
          "hasCart"
        ]
      }
    }
  },
  {
    "id": "cart_required_for_open_aisle_shelf_pickup",
    "text": "Shelf interactions from open cart-accessible aisles should be done with the cart present.",
    "abstraction": {
      "state_properties": {
        "openAisleShelfSpot": {
          "and": [
            "adjShelf",
            {
              "gt": [
                "freeWidthH",
                1
              ]
            }
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "INTERACT",
          "openAisleShelfSpot",
          {
            "not": "hasCart"
          }
        ]
      }
    }
  },
  {
    "id": "cart_abandonment_only_at_parking_bays",
    "text": "A shopper may leave a cart only at designated wide parking bays at the mouths of narrow aisles.",
    "abstraction": {
      "state_properties": {
        "cartParkingBay": {
          "or": [
            "at(3,3)",
            "at(6,3)"
          ]
        }
      },
      "events": {
        "dropCart": {
          "pre": {
            "and": [
              "hasCart",
              "INTERACT"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "dropCart",
          {
            "not": "cartParkingBay"
          }
        ]
      }
    }
  },
  {
    "id": "must_reclaim_parked_cart",
    "text": "After parking a cart to enter a narrow aisle, the shopper is obliged to reclaim the cart before leaving the store.",
    "abstraction": {
      "state_properties": {
        "cartParkingBay": {
          "or": [
            "at(3,3)",
            "at(6,3)"
          ]
        }
      },
      "events": {
        "dropCart": {
          "pre": {
            "and": [
              "hasCart",
              "INTERACT",
              "cartParkingBay"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        },
        "reclaimParkedCart": {
          "pre": {
            "and": [
              {
                "not": "hasCart"
              },
              "INTERACT",
              "cartParkingBay"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "dropCart",
      "discharge": "reclaimParkedCart"
    }
  },
  {
    "id": "must_use_entrance_cart_station",
    "text": "Every shopper is obliged to collect a cart from the entrance cart station before proceeding with the trip.",
    "abstraction": {
      "state_properties": {
        "entranceCartStation": "at(1,7)"
      },
      "events": {
        "takeCartAtStation": {
          "pre": {
            "and": [
              "entranceCartStation",
              "INTERACT",
              {
                "not": "hasCart"
              }
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "START",
      "discharge": "takeCartAtStation"
    }
  },
  {
    "id": "on_foot_only_in_approved_zones",
    "text": "After entering the store, being without a cart is allowed only in the entrance zone, at cart parking bays, or inside single-file shelf aisles.",
    "abstraction": {
      "state_properties": {
        "entranceZone": {
          "or": [
            "at(0,7)",
            "at(1,7)"
          ]
        },
        "cartParkingBay": {
          "or": [
            "at(3,3)",
            "at(6,3)"
          ]
        },
        "singleFileShelfAisle": {
          "and": [
            "adjShelf",
            {
              "le": [
                "freeWidthH",
                1
              ]
            }
          ]
        },
        "allowedOnFootZone": {
          "or": [
            "entranceZone",
            "cartParkingBay",
            "singleFileShelfAisle"
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          {
            "not": "hasCart"
          },
          {
            "not": "allowedOnFootZone"
          }
        ]
      }
    }
  }
]
